eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   PROJECTS: () => (/* binding */ PROJECTS)\n/* harmony export */ });\nconst PROJECTS = [\n    {\n        slug: \"task-aware-traffic-sign-classification\",\n        title: \"Task-Aware Multi-Stage Framework for Traffic Sign Classification under Snow-Degraded Conditions\",\n        shortTitle: \"Task-Aware Traffic Sign Classification\",\n        subtitle: \"Robust Perception Under Adverse Weather & Environmental Domain Shift\",\n        category: \"Computer Vision · Robust Recognition\",\n        isResearch: true,\n        status: \"Manuscript in Preparation\",\n        year: 2026,\n        date: \"2025–2026\",\n        tags: [\n            \"Computer Vision\",\n            \"Traffic Sign Classification\",\n            \"Robust Machine Learning\",\n            \"Adverse Weather\",\n            \"Image Restoration\",\n            \"Deep Learning\",\n            \"Autonomous Vehicles\",\n            \"Environmental Domain Shift\"\n        ],\n        summary: \"An ongoing study of robust traffic sign recognition under snow-degraded visual conditions using a multi-stage restoration and classification approach.\",\n        description: \"An ongoing study of robust traffic sign classification under snow-degraded visual conditions. The research investigates a task-aware multi-stage approach that combines controlled environmental degradation, image restoration, and deep-learning-based classification to study how recognition performance changes when visual evidence becomes partially obscured or degraded.\",\n        keyContributions: [\n            \"Formulation of adverse snow weather as structured environmental domain shift\",\n            \"Task-aware multi-stage coordination between image enhancement and deep classification\",\n            \"Empirical investigation of feature recoverability prior to categorization heads\",\n            \"Rigorous research evolution from initial findings through revised experimental design\"\n        ],\n        technologies: [\n            \"PyTorch\",\n            \"EfficientNet\",\n            \"Deep Learning\",\n            \"Computer Vision\",\n            \"Adverse Weather\"\n        ],\n        featured: true,\n        trafficSignCaseStudy: {\n            shortTitle: \"Task-Aware Traffic Sign Classification\",\n            authors: [\n                \"Muhammad Hassan Askari\",\n                \"Muhammad Shareef\"\n            ],\n            institution: \"COMSATS University Islamabad\",\n            manuscriptStatusStatement: \"The manuscript is currently being refined, including methodological and experimental analysis. The work is intended for future submission to MDPI Sensors.\",\n            intendedVenue: \"MDPI Sensors (In Preparation)\",\n            publicDescription: \"An ongoing study of robust traffic sign classification under snow-degraded visual conditions. The research investigates a task-aware multi-stage approach that combines controlled environmental degradation, image restoration, and deep-learning-based classification to study how recognition performance changes when visual evidence becomes partially obscured or degraded.\",\n            motivation: {\n                overview: \"Reliable traffic-sign recognition is a foundational prerequisite for autonomous vehicles and advanced driver-assistance systems (ADAS). However, real-world deployment in cold-climate regions subjects visual perception systems to acute atmospheric and physical corruptions from falling and accumulated snow.\",\n                degradationEffects: [\n                    \"Visual occlusion from falling flakes and surface accumulation\",\n                    \"Reduced contrast and compressed dynamic range across scenes\",\n                    \"Atmospheric scattering and chromatic attenuation\",\n                    \"Partial loss of distinctive boundary geometries and glyphs\",\n                    \"Degradation of fine-grained discriminative texture details\"\n                ],\n                coreInquiry: \"The research investigates whether a task-aware, multi-stage processing pipeline can recover discriminative evidence prior to classification, improving recognition robustness when snow severely corrupts input imagery.\"\n            },\n            trajectoryFlow: [\n                \"Clean Traffic Sign Recognition\",\n                \"Adverse Weather Degradation\",\n                \"Snow-Degraded Visual Evidence\",\n                \"Image Enhancement\",\n                \"Task-Aware Multi-Stage Processing\",\n                \"Robust Traffic Sign Classification\",\n                \"Reliable Visual Intelligence\"\n            ],\n            methodologyPipeline: [\n                {\n                    stage: \"01\",\n                    title: \"Snow-Degraded Image\",\n                    description: \"Input image exhibiting atmospheric scattering, occlusion, and contrast attenuation.\"\n                },\n                {\n                    stage: \"02\",\n                    title: \"Data Preparation\",\n                    description: \"Standardized spatial normalization and resolution alignment.\"\n                },\n                {\n                    stage: \"03\",\n                    title: \"Image Enhancement / Restoration\",\n                    description: \"Deep-learning-based restoration targeted at reversing snow-induced corruption.\"\n                },\n                {\n                    stage: \"04\",\n                    title: \"Feature Recovery\",\n                    description: \"Reconstruction of boundary edges, chromatic contours, and interior symbology.\"\n                },\n                {\n                    stage: \"05\",\n                    title: \"Traffic Sign Classification\",\n                    description: \"Compound-scaled deep network mapping enhanced representations to class probabilities.\"\n                },\n                {\n                    stage: \"06\",\n                    title: \"Predicted Sign Class\",\n                    description: \"Robust categorical classification output resilient to adverse domain shift.\"\n                }\n            ],\n            datasetAndModels: {\n                datasetName: \"Belgium Traffic Sign Classification (BTSC)\",\n                classificationModel: \"EfficientNet (e.g., EfficientNet-B2 backbone)\",\n                enhancementModel: \"Deep-Learning-Based Image Restoration (e.g., HDCWNet)\",\n                highLevelNote: \"Architectures and benchmarks are treated at a conceptual technology level. Full training hyperparameters, augmentation schedules, loss weightings, and unpublished ablation configurations are preserved as private manuscript assets.\"\n            },\n            preliminaryFindings: {\n                badge: \"Preliminary Experimental Findings\",\n                statement: \"Early experimental evaluation indicates that the proposed multi-stage approach can substantially improve traffic-sign recognition under snow-degraded conditions. The experimental analysis is still being refined as part of the manuscript preparation process.\",\n                refinementNote: \"Exact quantitative benchmark tables, confusion matrices, and ablation statistics will be disclosed upon formal peer-reviewed publication in MDPI Sensors.\"\n            },\n            researchEvolution: {\n                steps: [\n                    \"Initial Study\",\n                    \"FIT 2025 Submission\",\n                    \"Reviewer Feedback\",\n                    \"Methodological Revision\",\n                    \"Task-Aware Reformulation\",\n                    \"Expanded Experimental Validation\",\n                    \"Manuscript Preparation\"\n                ],\n                narrative: \"The research originated as an initial study submitted to FIT 2025. Following constructive reviewer feedback, the investigation underwent systematic methodological revision—transitioning from a basic two-step pipeline to a task-aware formulation with expanded experimental validation, currently being finalized for submission to MDPI Sensors.\"\n            },\n            researchQuestions: [\n                \"How does snow-induced visual degradation affect traffic-sign classification?\",\n                \"Can image enhancement recover useful visual information before classification?\",\n                \"Can a task-aware multi-stage architecture improve robustness under snow-degraded conditions?\",\n                \"How should visual restoration and recognition be coordinated for adverse-weather perception?\",\n                \"How can robust visual recognition be extended to broader environmental domain shifts?\"\n            ],\n            broaderConnection: {\n                narrative: \"This research forms an integral pillar of my broader scholarly identity: Reliable Visual Intelligence Under Environmental Domain Shift. It investigates how visual AI systems preserve decision reliability when real-world deployment conditions diverge from clean training distributions.\",\n                trajectory: [\n                    \"Snow-Degraded Traffic Signs\",\n                    \"Robust Visual Recognition\",\n                    \"Environmental Domain Shift\",\n                    \"Few-Shot Adaptation\",\n                    \"Visual Reliability\",\n                    \"Multimodal AI\"\n                ],\n                conceptualSymmetry: \"Environmental domain shift in adverse weather conceptually mirrors unseen generator distribution shift in synthetic image detection—both demand robust representations invariant to out-of-distribution visual noise.\"\n            },\n            futureDirections: [\n                \"Stronger adverse-weather benchmark datasets with multi-level corruption annotations\",\n                \"Real-world snow-degraded traffic-sign imagery captured across diverse geographical climates\",\n                \"Domain generalization techniques invariant to diverse atmospheric conditions\",\n                \"Unsupervised and self-supervised domain adaptation for real-time video streams\",\n                \"Uncertainty-aware recognition quantifying classifier confidence under dense visual noise\",\n                \"Degradation-aware representation learning integrating physical weather models\",\n                \"Robustness evaluation under compound adverse conditions (co-occurring snow, fog, and nighttime lighting)\",\n                \"Multimodal perception fusing vision with radar/LiDAR under severe visual occlusions\"\n            ],\n            supervisorRelevance: \"Demonstrates foundational rigor in computer vision, domain shift analysis, and deep learning pipelines—positioning well for prospective graduate inquiries in robust visual perception, autonomous driving, and resilient AI systems.\"\n        }\n    },\n    {\n        slug: \"fewshot-aigd-shift\",\n        title: \"Few-Shot Adaptation for AI-Generated Image Detection under Unseen Generator Distribution Shift\",\n        shortTitle: \"FewShot-AIGD-Shift\",\n        category: \"Research\",\n        isResearch: true,\n        status: \"Experimental Validation Ongoing\",\n        year: 2026,\n        date: \"2026\",\n        repositoryVisibility: \"private\",\n        repositoryUrl: undefined,\n        tags: [\n            \"Computer Vision\",\n            \"Few-Shot Learning\",\n            \"Domain Shift\",\n            \"AI-Generated Image Detection\",\n            \"Model Adaptation\"\n        ],\n        summary: \"This research project investigates whether a pretrained AI-generated image detector can adapt to previously unseen image generators using only a small number of support examples.\",\n        description: \"AI-generated image synthesis systems evolve rapidly. When detectors encounter imagery produced by previously unobserved generative architectures, standard deep classifiers experience acute performance degradation. This research case study formulates detection under unseen generators as a distribution-shift challenge and investigates whether few-shot adaptation mechanisms can restore classification reliability with minimal target-domain supervisory support.\",\n        keyContributions: [\n            \"Controlled leave-generator-out evaluation protocol isolating unseen generator distribution shift\",\n            \"50-condition experimental matrix across 5 shot levels and 5 random seeds\",\n            \"Ablation comparing classifier-only adaptation versus last-block representation tuning\",\n            \"Comprehensive data-integrity and leakage audit across 11,000 research images\"\n        ],\n        technologies: [\n            \"PyTorch\",\n            \"ResNet-50\",\n            \"Python\",\n            \"Scientific Computing\",\n            \"Statistical Validation\"\n        ],\n        featured: true,\n        researchCaseStudy: {\n            researchQuestion: \"Can a detector trained on several image-generation sources be adapted to an unseen generator using only a few labeled examples?\",\n            questionContext: \"AI-generated image detectors can perform well on generators represented during training but may experience performance degradation when evaluated on images produced by previously unseen generative models. This project studies whether few-shot adaptation can reduce this distribution-shift problem.\",\n            motivation: \"AI-generated image generation systems evolve rapidly. A detector trained on known generators may encounter images produced by generators that were not represented during training. This creates a generator distribution shift. The project therefore investigates whether a model can adapt to a previously unseen generator with only a small support set rather than requiring large-scale retraining.\",\n            backbone: {\n                name: \"ResNet-50\",\n                description: \"The experimental framework uses ResNet-50 as the detection backbone and evaluates how its performance changes when exposed to previously unseen image-generation sources.\"\n            },\n            dataset: {\n                total: 11000,\n                sources: [\n                    {\n                        source: \"Nature\",\n                        images: 5000,\n                        type: \"Natural Images\",\n                        role: \"Natural Baseline\"\n                    },\n                    {\n                        source: \"Midjourney\",\n                        images: 1500,\n                        type: \"AI-Generated Images\",\n                        role: \"Unseen Generator\"\n                    },\n                    {\n                        source: \"Wukong\",\n                        images: 1500,\n                        type: \"AI-Generated Images\",\n                        role: \"Unseen Generator\"\n                    },\n                    {\n                        source: \"BigGAN\",\n                        images: 600,\n                        type: \"AI-Generated Images\",\n                        role: \"Training Generator\"\n                    },\n                    {\n                        source: \"ADM\",\n                        images: 600,\n                        type: \"AI-Generated Images\",\n                        role: \"Training Generator\"\n                    },\n                    {\n                        source: \"VQDM\",\n                        images: 600,\n                        type: \"AI-Generated Images\",\n                        role: \"Training Generator\"\n                    },\n                    {\n                        source: \"Glide\",\n                        images: 600,\n                        type: \"AI-Generated Images\",\n                        role: \"Training Generator\"\n                    },\n                    {\n                        source: \"Stable Diffusion v1.5\",\n                        images: 600,\n                        type: \"AI-Generated Images\",\n                        role: \"Training Generator\"\n                    }\n                ]\n            },\n            leaveGeneratorOut: {\n                trainingGenerators: [\n                    \"Nature (Real)\",\n                    \"BigGAN\",\n                    \"ADM\",\n                    \"VQDM\",\n                    \"Glide\",\n                    \"Stable Diffusion v1.5\"\n                ],\n                unseenGenerators: [\n                    \"Midjourney\",\n                    \"Wukong\"\n                ],\n                description: \"Midjourney and Wukong are intentionally excluded from model training and validation. They are treated as unseen generators. This creates a controlled generator distribution shift between training and evaluation.\"\n            },\n            dataSplit: {\n                training: 4000,\n                validation: 2000,\n                unseenTest: 2000,\n                realTest: 2000,\n                adaptationSupport: 1000,\n                total: 11000,\n                description: \"The research split reserves dedicated subsets for base training, in-distribution validation, balanced natural verification, and few-shot adaptation support draws.\"\n            },\n            fewShotConditions: {\n                shotLevels: [\n                    1,\n                    5,\n                    10,\n                    25,\n                    50\n                ],\n                seeds: [\n                    100,\n                    200,\n                    300,\n                    400,\n                    500\n                ],\n                unseenGenerators: [\n                    \"Midjourney\",\n                    \"Wukong\"\n                ],\n                totalRuns: 50,\n                description: \"For each shot level, adaptation is evaluated using five random seeds for each unseen generator: 2 unseen generators × 5 shot levels × 5 random seeds = 50 experimental runs.\"\n            },\n            adaptationStrategies: [\n                {\n                    id: \"classifier-only\",\n                    title: \"Classifier-Only Adaptation\",\n                    description: \"The pretrained feature extractor remains fixed while the classification layer is adapted using the few-shot support set.\",\n                    visual: \"Frozen Feature Extractor + Adapt Classifier\"\n                },\n                {\n                    id: \"last-block\",\n                    title: \"Last-Block Adaptation\",\n                    description: \"The final convolutional block is also updated during few-shot adaptation, allowing the experiment to investigate whether updating additional representation layers is beneficial when only a very small support set is available.\",\n                    visual: \"Adapt Last Convolutional Block + Adapt Classifier\"\n                }\n            ],\n            evaluationMetrics: {\n                primary: [\n                    \"Accuracy\",\n                    \"Precision\",\n                    \"Recall\",\n                    \"F1-score\",\n                    \"ROC-AUC\"\n                ],\n                statistical: [\n                    \"Mean\",\n                    \"Standard Deviation\",\n                    \"95% Confidence Intervals\",\n                    \"Hypothesis Tests\",\n                    \"Effect Sizes\",\n                    \"Per-Class Performance\",\n                    \"Confusion Matrices\",\n                    \"ROC Analysis\"\n                ]\n            },\n            preliminaryResults: {\n                metric: \"Mean ROC-AUC\",\n                badge: \"Preliminary\",\n                columns: [\n                    \"1-shot\",\n                    \"5-shot\",\n                    \"10-shot\",\n                    \"25-shot\",\n                    \"50-shot\"\n                ],\n                rows: [\n                    {\n                        generator: \"Midjourney\",\n                        scores: [\n                            0.9064,\n                            0.9459,\n                            0.9571,\n                            0.9588,\n                            0.9624\n                        ]\n                    },\n                    {\n                        generator: \"Wukong\",\n                        scores: [\n                            0.9090,\n                            0.9509,\n                            0.9542,\n                            0.9610,\n                            0.9620\n                        ]\n                    }\n                ],\n                chartNote: \"The current results indicate increasing ROC-AUC across the evaluated few-shot conditions, particularly at lower support-set sizes. These results remain preliminary pending completion of the remaining baseline and statistical validation work.\"\n            },\n            dataIntegrity: {\n                duplicatePaths: {\n                    total: 11000,\n                    unique: 11000,\n                    duplicated: 0\n                },\n                trainTestOverlap: {\n                    train: 4000,\n                    test: 4000,\n                    overlap: 0\n                },\n                sampledPathExistence: {\n                    checked: 1000,\n                    existing: 1000\n                },\n                auditNote: \"The research split has been audited for duplicate paths, train/test exact path overlap, and sampled path existence. These reflect basic data-integrity and leakage checks rather than claiming complete elimination of all conceivable leakage forms.\"\n            },\n            validationTimeline: {\n                completed: [\n                    \"Research split generated\",\n                    \"Leave-generator-out protocol established\",\n                    \"Train/test path leakage audit\",\n                    \"Duplicate-path audit\",\n                    \"Path existence audit\",\n                    \"Few-shot experiments\",\n                    \"Five random seeds per few-shot condition\",\n                    \"Confidence intervals\",\n                    \"Adaptation ablation\",\n                    \"Statistical artifact generation\",\n                    \"Validation manifest\"\n                ],\n                inProgress: [\n                    \"Multi-seed baseline evaluation\",\n                    \"Verification of Cohen's d calculations\",\n                    \"Multiple-comparison correction\",\n                    \"Paired statistical tests for ablation\",\n                    \"Baseline vs. few-shot statistical comparison\",\n                    \"Per-class metrics\",\n                    \"Final ROC analysis\",\n                    \"Final paper tables and figures\"\n                ]\n            },\n            experimentalArtifacts: {\n                categories: [\n                    \"Few-Shot Results\",\n                    \"Baseline Results\",\n                    \"Ablation Results\",\n                    \"Confidence Intervals\",\n                    \"Statistical Analysis\",\n                    \"Research Split\",\n                    \"Training History\",\n                    \"Validation Manifest\",\n                    \"Figures\"\n                ],\n                sampleInternalFilenames: [\n                    \"resnet50_clean_unseen_fewshot_results.csv\",\n                    \"resnet50_clean_fewshot_summary.csv\",\n                    \"adaptation_ablation_results.csv\",\n                    \"adaptation_ablation_summary.csv\",\n                    \"confidence_intervals.csv\",\n                    \"research_split_v1.csv\",\n                    \"resnet50_training_history.csv\",\n                    \"final_validation_manifest.json\"\n                ],\n                note: \"Internal experimental artifacts cataloged for manuscript preparation; not downloadable resources.\"\n            },\n            researchInterpretation: [\n                \"Whether few-shot adaptation improves detection on unseen generators\",\n                \"How performance changes as support examples increase\",\n                \"Whether classifier-only adaptation is sufficient\",\n                \"Whether adapting the final convolutional block provides additional benefit\",\n                \"How robust the observed improvements are across random seeds\",\n                \"Whether statistical evidence supports the observed differences\"\n            ],\n            broaderConnection: {\n                environmentalShift: \"Traffic sign recognition under snow examines Environmental Domain Shift.\",\n                generatorShift: \"FewShot-AIGD-Shift examines Generator Distribution Shift.\",\n                sharedParadigm: [\n                    \"Training Distribution\",\n                    \"Distribution Shift\",\n                    \"Limited / Changed Evidence\",\n                    \"Adaptation\",\n                    \"Reliable Prediction\"\n                ],\n                trajectory: [\n                    \"Environmental Degradation\",\n                    \"Robust Visual Recognition\",\n                    \"Distribution Shift\",\n                    \"Few-Shot Adaptation\",\n                    \"Visual Reliability\",\n                    \"Multimodal AI\"\n                ],\n                narrative: \"Both projects study the identical fundamental question: How can visual AI models adapt their representations when deployed under distribution shifts not encountered during training?\"\n            },\n            futureResearchQuestions: [\n                \"How can few-shot adaptation become more reliable when the target generator differs substantially from all training distributions?\",\n                \"Can uncertainty estimates identify when an AI-generated image detector is operating outside its learned distribution?\",\n                \"Can adaptation strategies dynamically determine which representation layers should be updated?\",\n                \"Can generator-invariant representations reduce dependence on the specific synthetic sources observed during training?\",\n                \"Can multimodal evidence improve AI-generated image detection when visual artifacts alone become ambiguous?\"\n            ],\n            supervisorRelevance: {\n                statement: \"This project strengthened my interest in learning under distribution shift, especially scenarios where a model encounters conditions that were not represented during training.\",\n                connectedFields: [\n                    \"Computer Vision\",\n                    \"Domain Adaptation\",\n                    \"Few-Shot Learning\",\n                    \"Robust Machine Learning\",\n                    \"AI-Generated Content Detection\",\n                    \"Trustworthy AI\",\n                    \"Multimodal AI\",\n                    \"Distribution Shift\"\n                ]\n            }\n        }\n    },\n    {\n        slug: \"ai-email-copilot\",\n        title: \"AI Email Copilot\",\n        shortTitle: \"Email-Copilot\",\n        category: \"Research Project\",\n        isResearch: true,\n        status: \"Completed Prototype\",\n        year: 2025,\n        date: \"2024–2025\",\n        tags: [\n            \"RAG\",\n            \"LLMs\",\n            \"Information Retrieval\",\n            \"FastAPI\",\n            \"PostgreSQL\",\n            \"pgvector\"\n        ],\n        summary: \"An AI email assistant exploring retrieval-augmented generation for grounding language-model responses in user-specific information.\",\n        description: \"Investigates the mechanics of information grounding in large language models via dense semantic retrieval. The system pairs contextual vector indexing with structured relational memory to synthesize grounded, verifiable draft responses without parametric hallucination.\",\n        keyContributions: [\n            \"Dense vector indexing using pgvector over personal communication archives\",\n            \"Prompt orchestration and retrieval-augmented context injection pipeline\",\n            \"Robust asynchronous backend architecture with FastAPI and PostgreSQL\"\n        ],\n        technologies: [\n            \"FastAPI\",\n            \"PostgreSQL\",\n            \"pgvector\",\n            \"Python\",\n            \"LangChain/LlamaIndex\",\n            \"TypeScript\"\n        ],\n        repositoryVisibility: \"public\",\n        repositoryUrl: \"https://github.com/AskariSyed/AI-Email-Copilot\",\n        githubUrl: \"https://github.com/AskariSyed/AI-Email-Copilot\",\n        featured: true\n    },\n    {\n        slug: \"decentralized-greedy-interview-scheduling\",\n        title: \"Decentralized Greedy Scheduling for Interview Allocation at Job Fairs\",\n        shortTitle: \"Greedy Interview Scheduling\",\n        subtitle: \"Algorithm Design, Complexity, and Empirical Evaluation\",\n        year: 2026,\n        date: \"2026\",\n        category: \"Algorithms & Optimization\",\n        isResearch: true,\n        status: \"Initial Research Phase\",\n        repositoryVisibility: \"private\",\n        repositoryUrl: undefined,\n        featured: true,\n        tags: [\n            \"Algorithms\",\n            \"Scheduling\",\n            \"Optimization\",\n            \"Greedy Algorithms\",\n            \"Fairness\",\n            \"Concurrency\",\n            \"Software Systems\"\n        ],\n        summary: \"An ongoing study of greedy scheduling, conflict-aware temporal allocation, fairness, and transactional revalidation for interview assignment in job fairs.\",\n        description: \"Interview allocation at a large-scale job fair presents a complex two-sided scheduling challenge where multiple companies and students share constrained temporal resources. This research models the problem under coupled availability, non-overlapping intervals, lunch restrictions, and mandatory buffers, investigating an efficient conflict-jumping greedy heuristic paired with database-level transactional revalidation.\",\n        keyContributions: [\n            \"Two-sided scheduling formalization with joint temporal and buffer constraints\",\n            \"Conflict-jumping heuristic preventing fine-grained minute-by-minute search stalls\",\n            \"Empirical evaluation of buffer duration impact on overall allocation fraction\",\n            \"Transaction-based optimistic revalidation mitigating concurrent scheduling races\"\n        ],\n        technologies: [\n            \"C# / .NET\",\n            \"Algorithm Design\",\n            \"Synthetic Simulation\",\n            \"Complexity Analysis\",\n            \"Relational Concurrency\"\n        ],\n        schedulingCaseStudy: {\n            subtitle: \"Algorithm Design, Complexity, and Empirical Evaluation\",\n            researchStatusStatement: \"This project is currently in the early stages of research and empirical validation. The scheduling formulation, greedy heuristic, complexity analysis, simulation methodology, and evaluation framework are being refined.\",\n            researchQuestion: \"How can interview requests be efficiently allocated across shared student and company resources while respecting temporal constraints, fairness considerations, and concurrent scheduling requests?\",\n            twoSidedConstraints: [\n                {\n                    title: \"Two-Sided Assignment\",\n                    description: \"Companies need to interview multiple students, and students may be accepted by multiple companies.\"\n                },\n                {\n                    title: \"Simultaneous Exclusion\",\n                    description: \"Neither a student nor a company can participate in more than one interview simultaneously.\"\n                },\n                {\n                    title: \"Fixed Durations & Boundaries\",\n                    description: \"Interviews possess fixed durations and must fit strictly within declared operating hours.\"\n                },\n                {\n                    title: \"Mandatory Breaks\",\n                    description: \"Interviews cannot overlap designated shared event lunch breaks.\"\n                },\n                {\n                    title: \"Temporal Buffers\",\n                    description: \"A non-zero temporal buffer is required between consecutive interviews for transition and setup.\"\n                },\n                {\n                    title: \"Concurrent Dispatch\",\n                    description: \"Multiple company representatives may trigger automated scheduling concurrently in a decentralized system.\"\n                }\n            ],\n            motivation: \"Interview scheduling at a job fair is fundamentally distinct from ordinary single-resource slot assignment. Every scheduling decision simultaneously ties up two distinct entities: a specific student and a company recruitment team. Because in-demand students receive multiple interview acceptances and companies maintain long queues of candidates, scheduling decisions exert cascading ripple effects. The scheduler must continuously balance student availability, company availability, hard temporal boundaries, and candidate processing order.\",\n            greedyAlgorithm: {\n                overview: \"The core scheduler employs a decentralized first-fit greedy heuristic augmented with conflict-jumping to rapidly determine earliest feasible time slots without fine-grained time-stepped scanning.\",\n                pipelineSteps: [\n                    {\n                        step: \"01\",\n                        title: \"Accepted Requests Ingestion\",\n                        description: \"Collects pending accepted interview requests waiting to be scheduled for the calling company.\"\n                    },\n                    {\n                        step: \"02\",\n                        title: \"Priority Ordering\",\n                        description: \"Sorts candidate requests using a heuristic priority rule based on the candidate student's existing interview commitments.\"\n                    },\n                    {\n                        step: \"03\",\n                        title: \"First-Fit Search\",\n                        description: \"Iterates sequentially from the configured event start time to locate the earliest mutually open slot.\"\n                    },\n                    {\n                        step: \"04\",\n                        title: \"Conflict Detection\",\n                        description: \"Checks whether candidate intervals clash with company bookings, student bookings, lunch windows, or boundary limits.\"\n                    },\n                    {\n                        step: \"05\",\n                        title: \"Conflict Jumping\",\n                        description: \"When an overlap occurs, the search pointer jumps directly to the conclusion of the blocking interview plus required buffer.\"\n                    },\n                    {\n                        step: \"06\",\n                        title: \"Candidate Assignment\",\n                        description: \"Constructs an in-memory provisional schedule reservation for the current request.\"\n                    },\n                    {\n                        step: \"07\",\n                        title: \"Local Busy-List Update\",\n                        description: \"Immediately updates in-memory availability structures to prevent subsequent requests within the batch from self-conflicting.\"\n                    },\n                    {\n                        step: \"08\",\n                        title: \"Database Revalidation\",\n                        description: \"Opens an isolated database transaction, queries the latest persisted state, and verifies zero inter-company collision.\"\n                    },\n                    {\n                        step: \"09\",\n                        title: \"Commit / Rollback\",\n                        description: \"Commits allocations if all constraints remain unviolated; otherwise triggers transactional rollback and retry.\"\n                    }\n                ],\n                priorityRuleNote: \"Requests are ordered according to the number of interviews already scheduled for each student (students with more existing commitments processed first). This serves as an empirical heuristic priority rule rather than an optimality guarantee.\",\n                conflictJumpingNote: \"Rather than advancing minute-by-minute through occupied periods, the search pointer advances directly to max(end_time + buffer) of detected conflicts. This eliminates thousands of redundant validity evaluations.\"\n            },\n            formalModel: {\n                definitions: [\n                    {\n                        symbol: \"C\",\n                        meaning: \"Set of participating companies: {c_1, c_2, ..., c_m}\"\n                    },\n                    {\n                        symbol: \"S\",\n                        meaning: \"Set of eligible students: {s_1, s_2, ..., s_n}\"\n                    },\n                    {\n                        symbol: \"(c, s)\",\n                        meaning: \"Accepted interview request between company c and student s\"\n                    },\n                    {\n                        symbol: \"d_c\",\n                        meaning: \"Fixed interview duration configured for company c\"\n                    },\n                    {\n                        symbol: \"t_{c,s}\",\n                        meaning: \"Assigned starting timestamp for interview (c, s)\"\n                    },\n                    {\n                        symbol: \"β\",\n                        meaning: \"Mandatory transition buffer duration between consecutive interviews\"\n                    },\n                    {\n                        symbol: \"I_{c,s}\",\n                        meaning: \"Occupied temporal interval: [t_{c,s}, t_{c,s} + d_c)\"\n                    },\n                    {\n                        symbol: \"[T_{start}, T_{end}]\",\n                        meaning: \"Permissible daily operating window for interview sessions\"\n                    },\n                    {\n                        symbol: \"[T_{L,start}, T_{L,end}]\",\n                        meaning: \"Restricted mid-day lunch break window\"\n                    }\n                ],\n                constraints: [\n                    {\n                        id: \"F1\",\n                        name: \"Temporal Operating Feasibility\",\n                        formula: \"T_{start} \\\\le t_{c,s} \\\\quad \\\\wedge \\\\quad t_{c,s} + d_c \\\\le T_{end} \\\\quad \\\\wedge \\\\quad I_{c,s} \\\\cap [T_{L,start}, T_{L,end}] = \\\\emptyset\",\n                        explanation: \"Every scheduled session must execute entirely within operating hours and strictly avoid the lunch hiatus.\"\n                    },\n                    {\n                        id: \"F2\",\n                        name: \"Company Non-Overlap Constraint\",\n                        formula: \"\\\\forall s' \\\\ne s: \\\\quad [t_{c,s}, t_{c,s} + d_c + \\\\beta) \\\\cap [t_{c,s'}, t_{c,s'} + d_c + \\\\beta) = \\\\emptyset\",\n                        explanation: \"A single company recruitment team cannot conduct concurrent sessions, with buffer β enforced between bookings.\"\n                    },\n                    {\n                        id: \"F3\",\n                        name: \"Student Non-Overlap Constraint\",\n                        formula: \"\\\\forall c' \\\\ne c: \\\\quad [t_{c,s}, t_{c,s} + d_c + \\\\beta) \\\\cap [t_{c',s}, t_{c',s} + d_{c'} + \\\\beta) = \\\\emptyset\",\n                        explanation: \"A student cannot participate in multiple simultaneous interviews across distinct company recruitment teams.\"\n                    }\n                ]\n            },\n            complexityAnalysis: {\n                sorting: \"O(R \\\\log R) where R represents the count of candidate requests in the scheduling batch.\",\n                conflictChecking: \"O(k_c + k_s) per evaluation step, where k_c and k_s are relevant company and student reservations.\",\n                searchBound: \"Constant upper bound of 5,000 search iterations per candidate request enforced in the software implementation.\",\n                worstCaseBound: \"O(R \\\\log R + 5000R(k_c + k_s)) under enforced iteration bounds.\",\n                empiricalFit: \"Empirical log-log regression across simulated workloads yields a scaling exponent of approximately 1.08.\",\n                distinctionNote: \"Important methodological note: The empirical scaling exponent near 1.08 observed in synthetic testing is an empirical observation of typical performance, not a mathematical proof of near-linear theoretical worst-case complexity.\"\n            },\n            empiricalEvaluation: {\n                overview: \"Because operational job-fair scheduling execution logs are not publicly standardized or available, the current empirical evaluation relies on parametric synthetic scheduling scenarios.\",\n                scenarioType: \"Synthetic Scheduling Scenarios\",\n                testedRequestRange: \"32 to 1,454 synthetic requests across diverse student acceptance distributions\",\n                observedLogLogExponent: \"1.08\",\n                investigatedFactors: [\n                    \"Request volume scaling and computational throughput\",\n                    \"Scheduling contention and two-sided bottleneck emergence\",\n                    \"Company invocation order sensitivity\",\n                    \"Buffer duration variation (0 to 600 seconds)\",\n                    \"Priority ordering effects on throughput vs. fairness\",\n                    \"Overall scheduling success fraction under peak loads\"\n                ],\n                preliminaryNotice: \"All quantitative outcomes represent preliminary simulation findings from ongoing doctoral preparation research and are subject to expanded benchmark verification.\"\n            },\n            bufferExperiment: {\n                baselineBuffer: \"90 seconds (system default transition allowance)\",\n                testedRange: \"0 seconds to 600 seconds (10-minute maximum)\",\n                observations: [\n                    {\n                        bufferSeconds: 0,\n                        successRate: 76.0\n                    },\n                    {\n                        bufferSeconds: 90,\n                        successRate: 71.4\n                    },\n                    {\n                        bufferSeconds: 180,\n                        successRate: 66.8\n                    },\n                    {\n                        bufferSeconds: 300,\n                        successRate: 61.2\n                    },\n                    {\n                        bufferSeconds: 600,\n                        successRate: 53.8\n                    }\n                ],\n                analysis: \"Increasing the inter-interview buffer β noticeably contracts total scheduling capacity, reducing scheduling fraction from ~76.0% (β=0s) to ~53.8% (β=600s). The 90-second configuration represents an operational compromise between student physical movement across booths and aggregate scheduling density.\"\n            },\n            fairnessAnalysis: {\n                currentRuleDescription: \"The current priority heuristic prioritizes requests for students who already possess higher scheduled interview counts, attempting to pack dense schedules efficiently.\",\n                observations: [\n                    \"Preliminary simulations indicate the heuristic does not necessarily increase aggregate event-wide scheduling capacity.\",\n                    \"Processing order shifts significantly, often consolidating slots among already in-demand candidates.\",\n                    \"Early observations suggest the current rule may inadvertently reduce fairness for candidates with fewer total interview invitations.\"\n                ],\n                futurePolicies: [\n                    \"Students with fewer existing opportunities processed first (max-min equity)\",\n                    \"Guaranteed minimum interview quota allocation\",\n                    \"Fairness-aware multi-criteria ranking functions\",\n                    \"Dynamic opportunity-weighted priority queues\",\n                    \"Fairness-capacity Pareto frontier analysis\"\n                ]\n            },\n            concurrencyModel: {\n                problemStatement: \"In a decentralized event where multiple company booth managers click 'Generate Schedule' concurrently, independently calculated in-memory schedules can race for identical open student slots.\",\n                pipeline: [\n                    \"Generate candidate schedule in memory using local snapshot\",\n                    \"Open isolated database transaction with read consistency\",\n                    \"Fetch persisted ground-truth intervals for target students & company\",\n                    \"Perform strict database-level conflict re-verification\",\n                    \"If conflict detected: Rollback transaction & signal retry required\",\n                    \"If valid: Persist allocated records & commit atomic transaction\"\n                ],\n                mechanism: \"Optimistic Transactional Revalidation\",\n                guaranteeNote: \"This approach provides a robust atomic safety net preventing double-booking without requiring global pessimistic locking across the entire student body during heuristic search.\"\n            },\n            walkInSupport: {\n                description: \"The underlying job-fair scheduling architecture additionally accommodates spontaneous on-site walk-in candidates without perturbing already locked interview commitments.\",\n                prerequisites: [\n                    \"Company booth recruitment team must be logged in and currently present\",\n                    \"Current system clock must fall strictly within the active designated walk-in window\",\n                    \"Walk-in intake mode must be explicitly toggled active by company recruiters\",\n                    \"Candidate student must hold verified registration within the institutional portal\"\n                ]\n            },\n            realWorldConnection: {\n                narrative: \"This algorithmic research originated directly from engineering challenges encountered while designing and deploying the enterprise CUI Wah Job Fair Portal. Real-world observations of recruiter delays, double-booking contention, and student queueing motivated the formulation of formal scheduling models, conflict-jumping heuristics, and concurrency validation.\",\n                originSystem: \"CUI Wah Job Fair Portal\",\n                evolutionSteps: [\n                    \"Operational Job Fair Observations\",\n                    \"Two-Sided Constraint Formalization\",\n                    \"Mathematical Problem Modeling\",\n                    \"Greedy Heuristic Formulation\",\n                    \"Conflict-Jumping Search Optimization\",\n                    \"Synthetic Simulation & Scaling Analysis\",\n                    \"Database Transactional Revalidation\",\n                    \"Integrated Production-Ready Scheduling Engine\"\n                ]\n            },\n            futureDirections: [\n                \"Formulation of multi-objective fairness-aware scheduling priority rules\",\n                \"Empirical benchmarking against alternative greedy heuristics (e.g., Shortest Processing Time, Slack Time)\",\n                \"Investigation of local search and metaheuristic approaches (Simulated Annealing, Tabu Search)\",\n                \"Exact Integer Linear Programming (ILP) formulations for small-to-medium problem instances\",\n                \"Bipartite matching and network flow reductions for constrained sub-problems\",\n                \"Maximum-flow formulations with non-uniform time slot capacities\",\n                \"Scaling evaluations on ultra-large synthetic workloads (10,000+ requests)\",\n                \"Acquisition and benchmarking against anonymized real-world job fair event logs\",\n                \"Rigorous statistical hypothesis testing and variance analysis across random request graphs\",\n                \"Distributed consensus protocols and formal concurrency throughput bounds\",\n                \"Pareto-optimal frontier analysis balancing total event capacity against candidate fairness\"\n            ],\n            limitations: [\n                \"Experimental evaluations currently rely exclusively on synthetic scenarios; real-world event logs are not yet available.\",\n                \"Greedy heuristics make locally optimal decisions and do not guarantee global optimality or maximum possible matching.\",\n                \"Company call order introduces scheduling path dependency, where earlier callers secure preferable time slots.\",\n                \"The current priority heuristic requires further investigation regarding its fairness impact on low-frequency interviewees.\",\n                \"The implemented 5,000-iteration search ceiling may theoretically truncate search in extreme hyper-dense edge scenarios.\",\n                \"Optimistic transaction revalidation eliminates silent collisions but requires conflicting companies to retry scheduling.\",\n                \"Statistical tests and effect-size analyses are currently in preliminary development.\",\n                \"Formal mathematical proofs of approximation ratios under two-sided buffer constraints remain an open inquiry.\"\n            ]\n        }\n    },\n    {\n        slug: \"cui-wah-job-fair-portal\",\n        title: \"CUI Wah Job Fair Portal\",\n        shortTitle: \"Job-Fair-Portal\",\n        category: \"Applied Systems\",\n        isResearch: false,\n        status: \"Production Deployment\",\n        year: 2024,\n        date: \"2024\",\n        tags: [\n            \"Applied Software Engineering\",\n            \"Information Systems\",\n            \"Full-Stack Development\"\n        ],\n        summary: \"Production-grade enterprise recruitment and student coordination portal designed for COMSATS University Islamabad.\",\n        description: \"Demonstrates high-scale systems engineering capabilities. Built to serve hundreds of graduating candidates, recruitment panels, and academic administrators with secure role-based access, real-time interview scheduling, and resilient data storage.\",\n        keyContributions: [\n            \"High-throughput RESTful backend built with ASP.NET Core & .NET 8\",\n            \"Relational schema design and indexing in PostgreSQL\",\n            \"Responsive client applications developed in React, TypeScript, and Flutter\"\n        ],\n        technologies: [\n            \"ASP.NET Core\",\n            \".NET 8\",\n            \"PostgreSQL\",\n            \"React\",\n            \"TypeScript\",\n            \"Vite\",\n            \"Flutter\"\n        ],\n        featured: false\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./data/projects.ts\n");

